<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $convs = App\Models\WaBotConversation::latest('id')->take(5)->get(); echo 'Found ' . count($convs) . ' convs' . PHP_EOL; foreach($convs as $conv) { echo 'Conv ' . $conv->id . ' from_jid=' . $conv->from_jid . ' role=' . $conv->identified_role . PHP_EOL; foreach($conv->messages as $msg) { echo '  ' . $msg->id . ' - ' . $msg->role . ' - ' . substr($msg->content, 0, 50) . PHP_EOL; } }
